from prices import subtotal

def receipt(prices, discount=0, include_count=False):
    if include_count:
        prices = list(prices)
    text = f"Total: {subtotal(prices, discount=discount)}"
    if include_count:
        text += f"\nItems: {len(prices)}"
    return text

