def subtotal(prices, discount=0):
    if not isinstance(discount, int):
        raise TypeError("discount must be an integer percent")
    if not 0 <= discount <= 100:
        raise ValueError("discount must be between 0 and 100")
    total = sum(prices)
    return total if discount == 0 else total * (100 - discount) / 100

