import unittest

from prices import subtotal


class SubtotalTests(unittest.TestCase):
    def test_default_keeps_integer_total(self):
        self.assertEqual(subtotal([10, 20]), 30)
        self.assertIsInstance(subtotal([10, 20]), int)

    def test_discount(self):
        self.assertEqual(subtotal([10, 20], discount=50), 15.0)

    def test_discount_boundaries(self):
        self.assertEqual(subtotal([10, 20], discount=0), 30)
        self.assertEqual(subtotal([10, 20], discount=100), 0.0)

    def test_empty_prices(self):
        self.assertEqual(subtotal([], discount=50), 0.0)

    def test_iterable_prices(self):
        self.assertEqual(subtotal(iter([10, 20]), discount=50), 15.0)

    def test_out_of_range_discount(self):
        for discount in (-1, 101):
            with self.subTest(discount=discount):
                with self.assertRaises(ValueError):
                    subtotal([10, 20], discount=discount)

    def test_noninteger_discount(self):
        for discount in (0.5, 50.0, "50", None):
            with self.subTest(discount=discount):
                with self.assertRaises(TypeError):
                    subtotal([10, 20], discount=discount)

