import unittest
from receipt import receipt

class ReceiptTests(unittest.TestCase):
    def test_total(self):
        self.assertEqual(receipt([2, 3]), "Total: 5")

    def test_discount(self):
        self.assertEqual(receipt([10, 20], discount=50), "Total: 15.0")

    def test_count(self):
        self.assertEqual(receipt([10, 20], include_count=True), "Total: 30\nItems: 2")

    def test_discount_with_count(self):
        self.assertEqual(receipt([10, 20], discount=50, include_count=True), "Total: 15.0\nItems: 2")

    def test_empty_count(self):
        self.assertEqual(receipt([], include_count=True), "Total: 0\nItems: 0")

    def test_iterable_count(self):
        self.assertEqual(receipt(iter([10, 20]), discount=50, include_count=True), "Total: 15.0\nItems: 2")

    def test_iterable_default(self):
        self.assertEqual(receipt(iter([10, 20])), "Total: 30")

    def test_explicit_defaults(self):
        self.assertEqual(receipt([10, 20], discount=0, include_count=False), "Total: 30")

    def test_invalid_discount(self):
        for discount in (-1, 101):
            with self.subTest(discount=discount):
                with self.assertRaises(ValueError):
                    receipt([10, 20], discount=discount)
